// The same declaration form where the member belongs to a function of the
// module and to a plain object: the binding holds the value the chain
// assigns, and the functions below read it by the binding.
function Table () {}
var rows = Table.rows = []
var registry = {}
var seen = registry.seen = []

exports.Table = Table

exports.add = add
function add (name, amount) {
  rows.push(amount)
  seen.push(name)
}

exports.total = total
function total () {
  var sum = 0
  for (var i = 0; i < rows.length; i++) {
    sum += rows[i]
  }
  return sum
}

exports.names = names
function names () {
  return registry.seen
}

exports.count = count
function count () {
  return Table.rows.length
}
